#+ summary: Find signed nanopublications
#+ method: GET
#+ pagination: 1000
#+ endpoint_in_url: False

prefix np: <http://www.nanopub.org/nschema#>
prefix npa: <http://purl.org/nanopub/admin/>
prefix npx: <http://purl.org/nanopub/x/>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>
prefix dct: <http://purl.org/dc/terms/>

select ?np ?date ?pubkey ?superseded ?retracted where {
  graph npa:graph {
    ?np npa:hasHeadGraph ?h .
    ?np npa:creationDay ?__day_iri .
    ?np npa:creationMonth ?__month_iri .
    ?np npa:creationYear ?__year_iri .
    ?np dct:created ?date .
    ?np npa:hasValidSignatureForPublicKey ?__pubkey_xsd_string .
    bind(?__pubkey_xsd_string as ?pubkey)
  }
  bind(exists {
    graph npa:graph {
      ?newversion npa:hasHeadGraph ?nh .
      ?newversion npa:hasValidSignatureForPublicKey ?pubkey .
    }
    graph ?nh {
      ?newversion np:hasPublicationInfo ?ni .
    }
    graph ?ni {
      ?newversion npx:supersedes ?np .
    }
  } as ?superseded )
  bind(exists {
    graph npa:graph {
      ?retraction npa:hasHeadGraph ?rh .
      ?retraction npa:hasValidSignatureForPublicKey ?pubkey .
    }
    graph ?rh {
      ?retraction np:hasAssertion ?ra .
    }
    graph ?ra {
      ?somebody npx:retracts ?np .
    }
  } as ?retracted )
}

#+ summary: Natural products structurally similar to chemicals
#+ description: How many compounds are structurally similar to eugenol and eugenyl acetate? Results are grouped by the parent taxon of the organism they were found in.
#+ endpoint: https://query.wikidata.org/bigdata/namespace/wdq/sparql
#+ pagination: 100
#+ method: GET
#+ tags:
#+   - Natural products
#+   - Structural similarity

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
#title:How many compounds are structurally similar to eugenol and eugenyl acetate? Results are grouped by the parent taxon of the organism they were found in.
PREFIX sachem: <http://bioinfo.uochb.cas.cz/rdf/v1.0/sachem#>
# prefixes needed for structural similarity search
PREFIX idsm: <https://idsm.elixir-czech.cz/sparql/endpoint/>
SELECT ?parent_taxon ?parent_taxon_name (COUNT(DISTINCT ?compound) AS ?count) WHERE {
    SERVICE idsm:wikidata {
        VALUES ?CUTOFF {
            "0.85"^^xsd:double
        }
        SERVICE <https://query.wikidata.org/bigdata/namespace/wdq/sparql> {
            VALUES ?derivatives {
                wd:Q423357
                wd:Q27116129
            }
            ?derivatives wdt:P233 ?smiles.
        }
        ?compound sachem:similarCompoundSearch [
        sachem:query ?smiles;
        sachem:cutoff ?CUTOFF
        ].
    } hint:Prior hint:runFirst TRUE.
    ?compound wdt:P703/wdt:P171 ?parent_taxon.
    ?parent_taxon wdt:P225 ?parent_taxon_name.
}
GROUP BY ?parent_taxon ?parent_taxon_name
ORDER BY DESC (?count)

#+ endpoint: http://virtuoso-midi.amp.ops.labs.vu.nl/sparql
#+ summary: MIDI tracks per piece, and their labels, parametrized

PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX midi: <http://purl.org/midi-ld/midi#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?track ?trackname WHERE {  
  ?_pattern_iri midi:hasTrack ?track .
  OPTIONAL { 
    ?track midi:hasEvent ?event .
    ?event a midi:TrackNameEvent .
    ?event rdfs:label ?trackname .
  }
}

#+ summary: Full-text search for Semantic Interoperability Profiles
#+ endpoint: https://query.np.trustyuri.net/repo/text
#+ method: GET

prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix np: <http://www.nanopub.org/nschema#>
prefix npa: <http://purl.org/nanopub/admin/>
prefix npx: <http://purl.org/nanopub/x/>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>
prefix dct: <http://purl.org/dc/terms/>
prefix fip: <https://w3id.org/fair/fip/terms/>
prefix search: <http://www.openrdf.org/contrib/lucenesail#>

select distinct ?np ?label ?description ?community ?date ?qualifier (max(?score) as ?maxscore) where {
  graph npa:graph {
    <https://w3id.org/np/RA27Uhopq4MHZziL2lKXX-wTb1jz4KVLbHaupxyAcCt9Y> npa:hasValidSignatureForPublicKey ?curators_np_pk .
    ?latest_curators_np npa:hasValidSignatureForPublicKey ?curators_np_pk .
    filter not exists { ?latest_curators_npx npx:invalidates ?latest_curators_np ; npa:hasValidSignatureForPublicKey ?curators_np_pk . }
    ?latest_curators_np np:hasAssertion ?latest_curators_assertion .
  }
  graph npa:networkGraph {
    ?latest_curators_np (npx:supersedes)* <https://w3id.org/np/RA27Uhopq4MHZziL2lKXX-wTb1jz4KVLbHaupxyAcCt9Y> .
    filter not exists { ?latest_curators_npxx npx:supersedes ?latest_curators_np }
  }

  graph npa:graph {
    ?np rdfs:label ?label ;
        npa:hasValidSignatureForPublicKey ?pubkey ;
        dct:created ?date .
    filter exists { ?np npx:hasNanopubType fip:Semantic-Interoperability-Profile . }
    filter not exists { ?np npx:hasNanopubType npx:ExampleNanopub . }
    filter not exists { ?npx npx:invalidates ?np ; npa:hasValidSignatureForPublicKey ?pubkey . }
  }
  optional { service <https://query.np.trustyuri.net/repo/full> {
    graph npa:graph {
      ?np np:hasAssertion ?a .
      ?np np:hasPublicationInfo ?i .
    }
    graph ?a {
      ?fip dct:description ?description .
      ?fip fip:declared-by ?community .

    }
    graph ?i {
      ?np npx:introduces ?fip .
    }
  } }
  ?np search:matches [
    search:query ?_query ;
    search:property ?property ;
    search:score ?score ;
    search:snippet ?snippet ] .
  optional { service <https://query.np.trustyuri.net/repo/type/cd51a3ac3e109fd12aacd5a324e14ebff644ce209c916e4250a3f50c2ddf0051> {  # (http://purl.org/nanopub/x/qualifies)
    graph npa:graph {
      ?qualification_np np:hasAssertion ?qa ;
        npa:hasValidSignatureForPublicKey ?qpubkey .
      filter not exists { ?qualification_npx npx:invalidates ?qualification_np ; npa:hasValidSignatureForPublicKey ?qpubkey . }
    }
    graph ?latest_curators_assertion {
      ?qpubkeys npx:hasPublicKey ?qpubkey .
    }
    graph ?qa {
      ?qualifier npx:qualifies ?np .
    }
  } }
  filter not exists { service <https://query.np.trustyuri.net/repo/type/39692876d0a7881c82e9a2cb6dc8859fb16fa69fb41cea2ace2f8fa70bc52aed> {  # (http://purl.org/nanopub/x/disapprovesOf)
    graph npa:graph {
      ?disapproval_np np:hasAssertion ?da ;
        npa:hasValidSignatureForPublicKey ?dpubkey .
      filter not exists { ?disapproval_npx npx:invalidates ?disapproval_np ; npa:hasValidSignatureForPublicKey ?dpubkey . }
    }
    graph ?latest_curators_assertion {
      ?qpubkeys npx:hasPublicKey ?dpubkey .
    }
    graph ?da {
      ?disapprover npx:disapprovesOf ?np .
    }
  } }
}
group by ?np ?description ?label ?community ?date ?qualifier
order by desc(?maxscore)

#+ summary: Assume an intention of marriage is close to the actual marriage. Assume a baptism is close to a child's birth. How many days after a marriage of a bride and groom is a child born? Syntax written in the Golden Agents ontology.
#+ endpoint: https://sparql.goldenagents.org/
#+ method: GET
#+ tags:
#+  - dtb

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ga: <https://data.goldenagents.org/ontology/>
PREFIX thes: <https://data.goldenagents.org/thesaurus/>

SELECT ?eventOTR ?eventDP ?father ?mother ?child ((?dateDP - ?dateOTR)/86400 AS ?days) WHERE {

  ?personMale a ga:Person ;
    ga:hasName ?father .

  ?personFemale a ga:Person ;
    ga:hasName ?mother .

  ?personChild a ga:Person ;
    ga:hasName ?child .

  ?eventOTR a thes:Ondertrouw ;
    ga:hasXSDDate ?dateOTR .

  ?eventDP a thes:Doop ;
    ga:hasXSDDate ?dateDP .

  ?bruidegom a thes:Bruidegom ;
    ga:carriedBy ?personMale ;
    ga:carriedIn ?eventOTR .

  ?bruid a thes:Bruid ;
    ga:carriedBy ?personFemale ;
    ga:carriedIn ?eventOTR .

  ?vader a thes:Vader ;
    ga:carriedBy ?personMale ;
    ga:carriedIn ?eventDP .

  ?moeder a thes:Moeder;
    ga:carriedBy ?personFemale ;
    ga:carriedIn ?eventDP .

  ?kind a thes:Kind ;
    ga:carriedBy ?personChild ;
    ga:carriedIn ?eventDP .

}

#+ summary: Assume an intention of marriage is close to the actual marriage. Assume a baptism is close to a child's birth. How many days after a marriage of a bride and groom is a child born?
#+ endpoint: https://sparql.goldenagents.org/
#+ method: GET
#+ tags:
#+  - dtb

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX roar: <https://data.goldenagents.org/ontology/roar/>
PREFIX thes: <https://data.goldenagents.org/thesaurus/>
PREFIX sem: <http://semanticweb.cs.vu.nl/2009/11/sem/>
PREFIX pnv: <https://w3id.org/pnv#>

SELECT ?eventOTR ?eventDP ?father ?mother ?child ((?dateDP - ?dateOTR)/86400 AS ?days) WHERE {

  # Doop
  GRAPH <https://data.goldenagents.org/datasets/ufab7d657a250e3461361c982ce9b38f3816e0c4b/saa_id_002_index_op_doopregisters> {
    ?personDPVader a roar:Person ;
        pnv:hasName/pnv:literalName ?father .

    ?personDPMoeder a roar:Person ;
        pnv:hasName/pnv:literalName ?mother .

    ?personDPKind a roar:Person ;
        pnv:hasName/pnv:givenName ?child .

    ?eventDP a thes:Doop ;
        sem:hasTimeStamp ?dateDP .

    ?vader a thes:Vader ;
        roar:carriedBy ?personDPVader ;
        roar:carriedIn ?eventDP .

    ?moeder a thes:Moeder ;
        roar:carriedBy ?personDPMoeder ;
        roar:carriedIn ?eventDP .

    ?kind a thes:Kind ;
        roar:carriedBy ?personDPKind ;
        roar:carriedIn ?eventDP .
  }

  # Ondertrouw
  GRAPH <https://data.goldenagents.org/datasets/ufab7d657a250e3461361c982ce9b38f3816e0c4b/saa_id_003_index_op_ondertrouwregisters> {
    ?personOTRBruidegom a roar:Person .

    ?personOTRBruid a roar:Person .

    ?eventOTR a thes:Ondertrouw ;
        sem:hasTimeStamp ?dateOTR .

    ?bruidegom a thes:Bruidegom ;
        roar:carriedBy ?personOTRBruidegom ;
        roar:carriedIn ?eventOTR .

    ?bruid a thes:Bruid ;
        roar:carriedBy ?personOTRBruid ;
        roar:carriedIn ?eventOTR .
  }

  # Linkset sameAs DTB-Ecartico
  GRAPH <https://data.goldenagents.org/datasets/u692bc364e9d7fa97b3510c6c0c8f2bb9a0e5123b/dtb_linkset_1_20210723> {
      ?personDPVader owl:sameAs ?personOTRBruidegom .
      ?personDPMoeder owl:sameAs ?personOTRBruid .
  }

}

#+ summary: Query to retrieve protein data
#+ description: Retrieve all properties that are mentioned in the Protein Profile. Proteins are grouped by their IRI, with multiple values possible. Defensive query assumes that data does not conform to Protein profile
#+ endpoint: https://swel.macs.hw.ac.uk/data/repositories/bioschemas
#+ defaults:
#+   - protein: https://disprot.org/DP00005
#+ tags:
#+   - Protein

PREFIX schema: <https://schema.org/>
PREFIX pav: <http://purl.org/pav/>
PREFIX void: <http://rdfs.org/ns/void#>

SELECT
    (GROUP_CONCAT(DISTINCT ?identifier;SEPARATOR=',') AS ?identifiers)
    (GROUP_CONCAT(DISTINCT ?name;SEPARATOR=',') AS ?names)
    (GROUP_CONCAT(DISTINCT ?associatedDisease;SEPARATOR=',') AS ?diseases)
    (GROUP_CONCAT(DISTINCT ?description;SEPARATOR=',') AS ?descriptions)
    (GROUP_CONCAT(DISTINCT ?annotation;SEPARATOR=',') AS ?annotations)
    (GROUP_CONCAT(DISTINCT ?encodedBy;SEPARATOR=',') AS ?genes)
    (GROUP_CONCAT(DISTINCT ?taxonomicRange;SEPARATOR=',') AS ?taxons)
    (GROUP_CONCAT(DISTINCT ?url;SEPARATOR=',') AS ?urls)
    (GROUP_CONCAT(DISTINCT ?alternateName;SEPARATOR=',') AS ?altNames)
    (GROUP_CONCAT(DISTINCT ?bioChemInteraction;SEPARATOR=',') AS ?interactions)
    (GROUP_CONCAT(DISTINCT ?bioChemSimilarity;SEPARATOR=',') AS ?similities)
    (GROUP_CONCAT(DISTINCT ?bioChemEntity;SEPARATOR=',') AS ?entities)
    (GROUP_CONCAT(DISTINCT ?sequence;SEPARATOR=',') AS ?sequences)
    (GROUP_CONCAT(DISTINCT ?molFunction;SEPARATOR=',') AS ?functions)
    (GROUP_CONCAT(DISTINCT ?representation;SEPARATOR=',') AS ?representations)
    (GROUP_CONCAT(DISTINCT ?image;SEPARATOR=',') AS ?images)
    (GROUP_CONCAT(DISTINCT ?process;SEPARATOR=',') AS ?processes)
    (GROUP_CONCAT(DISTINCT ?cellularLocation;SEPARATOR=',') AS ?locations)
    (GROUP_CONCAT(DISTINCT ?parentEntity;SEPARATOR=',') AS ?parents)
    (GROUP_CONCAT(DISTINCT ?sameAs;SEPARATOR=',') AS ?equivalences)
    (GROUP_CONCAT(DISTINCT ?dataset;SEPARATOR=',') AS ?datasets)
WHERE {
    VALUES ?class {<https://schema.org/Protein>
                    <https://bioschemas.org/Protein>
                    <http://schema.org/Protein>
                    <http://bioschemas.org/Protein>}
    GRAPH ?g {
# Bioschemas Minimal Properties
        ?_protein_iri a ?class .
        OPTIONAL {?_protein_iri schema:identifier ?identifier }
        OPTIONAL {?_protein_iri schema:name ?name }
## Bioschemas Recommended properties
        OPTIONAL {?_protein_iri schema:associatedDisease ?associatedDisease}
        OPTIONAL {?_protein_iri schema:description ?description}
        OPTIONAL {?_protein_iri schema:hasSequenceAnnotation ?annotation }
        OPTIONAL {?_protein_iri schema:includedInDataset ?dataset }
        OPTIONAL {?_protein_iri schema:isEncodedByBioChemEntity ?encodedBy}
        OPTIONAL {?_protein_iri schema:taxonomicRange ?taxonomicRange }
        OPTIONAL {?_protein_iri schema:url ?url}
## Bioschemas Optional properties
        OPTIONAL {?_protein_iri schema:alternateName ?alternateName}
        OPTIONAL {?_protein_iri schema:bioChemInteraction ?bioChemInteraction}
        OPTIONAL {?_protein_iri schema:bioChemSimilarity ?bioChemSimilarity}
        OPTIONAL {?_protein_iri schema:hasBioChemEntityPart ?bioChemEntity}
        OPTIONAL {?_protein_iri schema:hasBioPolymerSequence ?sequence}
        OPTIONAL {?_protein_iri schema:hasMolecularFunction ?molFunction}
        OPTIONAL {?_protein_iri schema:hasRepresentation ?representation }
        OPTIONAL {?_protein_iri schema:image ?image}
        OPTIONAL {?_protein_iri schema:isInvolvedInBiologicalProcess ?process}
        OPTIONAL {?_protein_iri schema:isLocatedInSubcellularLocation ?cellularLocation}
        OPTIONAL {?_protein_iri schema:isPartOfBioChemEntity ?parentEntity}
        OPTIONAL {?_protein_iri schema:sameAs ?sameAs }
    }
}

#+ summary: Query to retrieve chemical substance data
#+ description: Retrieve all properties that are mentioned in the ChemicalSubstance Profile.
#+ endpoint: https://swel.macs.hw.ac.uk/data/repositories/bioschemas
#+ defaults:
#+   - chemicalSubstance: https://nanocommons.github.io/specifications/jrc/index.html-5
#+ tags:
#+   - ChemicalSubstance

PREFIX schema: <https://schema.org/>
PREFIX pav: <http://purl.org/pav/>
PREFIX void: <http://rdfs.org/ns/void#>

SELECT
    (GROUP_CONCAT(DISTINCT ?identifier;SEPARATOR=',') AS ?identifiers)
    (GROUP_CONCAT(DISTINCT ?name;SEPARATOR=',') AS ?names)
    (GROUP_CONCAT(DISTINCT ?url;SEPARATOR=',') AS ?urls)
    (GROUP_CONCAT(DISTINCT ?chemicalComposition;SEPARATOR=',') AS ?chemicalCompositions)
    (GROUP_CONCAT(DISTINCT ?bioChemEntity;SEPARATOR=',') AS ?entities)
    (GROUP_CONCAT(DISTINCT ?alternateName;SEPARATOR=',') AS ?altNames)
    (GROUP_CONCAT(DISTINCT ?bioChemInteraction;SEPARATOR=',') AS ?interactions)
    (GROUP_CONCAT(DISTINCT ?bioChemSimilarity;SEPARATOR=',') AS ?similities)
    (GROUP_CONCAT(DISTINCT ?biologicalRole;SEPARATOR=',') AS ?biologicalRoles)
    (GROUP_CONCAT(DISTINCT ?chemicalRole;SEPARATOR=',') AS ?chemicalRoles)
    (GROUP_CONCAT(DISTINCT ?description;SEPARATOR=',') AS ?descriptions)
    (GROUP_CONCAT(DISTINCT ?image;SEPARATOR=',') AS ?images)
    (GROUP_CONCAT(DISTINCT ?sameAs;SEPARATOR=',') AS ?equivalences)
WHERE {
    VALUES ?class {<https://schema.org/ChemicalSubstance>
                    <https://bioschemas.org/ChemicalSubstance>
                    <http://schema.org/ChemicalSubstance>
                    <http://bioschemas.org/ChemicalSubstance>}
    GRAPH ?g {
# Bioschemas Minimal Properties
        ?_chemicalSubstance_iri a ?class .
        OPTIONAL {?_chemicalSubstance_iri schema:identifier ?identifier }
        OPTIONAL {?_chemicalSubstance_iri schema:name ?name }
        OPTIONAL {?_chemicalSubstance_iri schema:url ?url}
## Bioschemas Recommended properties
        OPTIONAL {?_chemicalSubstance_iri schema:chemicalComposition ?chemicalComposition}
        OPTIONAL {?_chemicalSubstance_iri schema:hasBioChemEntityPart ?bioChemEntity}
## Bioschemas Optional properties
        OPTIONAL {?_chemicalSubstance_iri schema:alternateName ?alternateName}
        OPTIONAL {?_chemicalSubstance_iri schema:bioChemInteraction ?bioChemInteraction}
        OPTIONAL {?_chemicalSubstance_iri schema:bioChemSimilarity ?bioChemSimilarity}
        OPTIONAL {?_chemicalSubstance_iri schema:biologicalRole ?biologicalRole}
        OPTIONAL {?_chemicalSubstance_iri schema:chemicalRole ?chemicalRole}
        OPTIONAL {?_chemicalSubstance_iri schema:description ?description}
        OPTIONAL {?_chemicalSubstance_iri schema:image ?image}
        OPTIONAL {?_chemicalSubstance_iri schema:sameAs ?sameAs }
    }
}

#+ summary: "Access to all SensorThings resources begins at the base resource path"
#+ description: "Navigating to the base resource path will return a JSON array of the available SensorThings resource endpoints. NOTE: make sure response content type is application/json"
#+ endpoint: "https://rohub2020-api-virtuoso-route-rohub.apps.paas-dev.psnc.pl/sparql"
