}

#+ summary: A hollistic bibliometric query for HiTS
#+ endpoint: https://query.wikidata.org/sparql
#+ tags:
#+   - bibliometrics
#defaultView:Graph

SELECT
  ?subject ?subjectLabel ?image1 ?rgb ?edgeLabel
  ?object ?objectLabel ?image2
WHERE {
  {
    SELECT
      (?lab as ?subject) (?labLabel as ?subjectLabel) ?image1
      ?rgb ?edgeLabel
      (?person as ?object) (?personLabel as ?objectLabel) ?image2
    WHERE {
      ?lab wdt:P361 wd:Q107380113 .
      ?person wdt:P1416 ?lab .
      OPTIONAL { ?lab wdt:P18 ?image1 }
      OPTIONAL { ?person wdt:P18 ?image2 }
      BIND("FF00FF" AS ?rgb) .
      BIND("affiliate" AS ?edgeLabel) .
    }
  }  
  UNION
  {
    SELECT
      (?lab as ?subject) (?labLabel as ?subjectLabel) ?image1
      ?rgb ?edgeLabel                                       
      (?manager as ?object) (?managerLabel as ?objectLabel) ?image2
    WHERE {
      ?lab wdt:P361 wd:Q107380113 .
      ?lab wdt:P1037 ?manager .
      OPTIONAL { ?lab wdt:P18 ?image1 }
      OPTIONAL { ?manager wdt:P18 ?image2 }
      BIND("FF00FF" AS ?rgb) .
      BIND("directed by" AS ?edgeLabel) .
    }
  }
  UNION
  {
    SELECT
      (?lab1 as ?subject) (?lab1Label as ?subjectLabel) ?image1
      ?rgb ?edgeLabel
      (?lab2 as ?object) (?lab2Label as ?objectLabel) ?image2
    WHERE {
      ?lab1 wdt:P361 wd:Q107380113 .
      ?lab2 wdt:P361 wd:Q107380113 .
      ?lab1 wdt:P361 ?lab2 .
      OPTIONAL { ?lab1 wdt:P18 ?image1 }
      OPTIONAL { ?lab2 wdt:P18 ?image2 }
      BIND("FF00FF" AS ?rgb) .
      BIND("part of" AS ?edgeLabel) .
    }
  }
  UNION 
  {
    SELECT
      (?author1 as ?subject) (?author1Label as ?subjectLabel) ?image1
      ?rgb ?edgeLabel
      (?author2 as ?object) (?author2Label as ?objectLabel) ?image2
    WHERE {
      wd:Q107380113 ^wdt:P361* / ^( wdt:P108 | wdt:P1416 | wdt:P463 ) ?author1 , ?author2 . 
      ?work wdt:P50 ?author1 , ?author2 .

      # Only display co-authorship for certain types of documents
      # Journal and conference articles, books, not (yet?) software
      VALUES ?publication_type { wd:Q13442814 wd:Q571 wd:Q26973022 wd:Q17928402 wd:Q947859 wd:Q54670950 }
      FILTER EXISTS { ?work wdt:P31 ?publication_type . }

      # No self-links.
      FILTER (?author1 != ?author2)

      # Images
      OPTIONAL { ?author1 wdt:P18 ?image1 }
      OPTIONAL { ?author2 wdt:P18 ?image2 }

      # Coloring of the nodes
      BIND("FFFFFF" AS ?rgb)
      BIND("coauthored" AS ?edgeLabel)
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,da,de,es,fr,jp,sv,ru,zh". }
}

#+ summary: Find things introduced in signed nanopublications that are not retracted or superseded
#+ method: GET
#+ pagination: 1000
#+ endpoint_in_url: False

prefix np: <http://www.nanopub.org/nschema#>
prefix npa: <http://purl.org/nanopub/admin/>
prefix npx: <http://purl.org/nanopub/x/>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>
prefix dct: <http://purl.org/dc/terms/>

select ?thing ?label ?description ?np ?date ?pubkey where {
  graph npa:graph {
    ?np npa:hasHeadGraph ?h .
    ?np npa:creationDay ?__day_iri .
    ?np npa:creationMonth ?__month_iri .
    ?np npa:creationYear ?__year_iri .
    ?np dct:created ?date .
    ?np npa:hasValidSignatureForPublicKey ?__pubkey_xsd_string .
    bind(?__pubkey_xsd_string as ?pubkey)
  }
  graph ?h {
    ?np np:hasAssertion ?a .
    ?np np:hasPublicationInfo ?i.
  }
  graph ?a {
    ?thing a ?_type_iri .
    ?thing rdfs:label ?label .
    optional {
      ?thing rdfs:comment ?comment .
    }
    optional {
      ?thing dct:description ?dctdesc .
    }
  }
  graph ?i {
    ?np (npx:introduces|npx:describes) ?thing .
  }
  filter not exists {
    graph npa:graph {
      ?newversion npa:hasHeadGraph ?nh .
      ?newversion npa:hasValidSignatureForPublicKey ?pubkey .
    }
    graph ?nh {
      ?newversion np:hasPublicationInfo ?ni .
    }
    graph ?ni {
      ?newversion npx:supersedes ?np .
    }
  }
  filter not exists {
    graph npa:graph {
      ?retraction npa:hasHeadGraph ?rh .
      ?retraction npa:hasValidSignatureForPublicKey ?pubkey .
    }
    graph ?rh {
      ?retraction np:hasAssertion ?ra .
    }
    graph ?ra {
      ?somebody npx:retracts ?np .
    }
  }
  bind(coalesce(?comment, ?dctdesc, "") as ?description)
  bind(concat(" ",lcase(str(?label))," ",lcase(str(?description))," ") as ?text)
  filter( contains(?text, lcase(str(?_searchterm))) )
}

#+ summary: Get FAIR Implementation Communities
#+ endpoint: https://query.np.trustyuri.net/repo/type/6a09747868afc83837e38d1bac79362fbcc3e2032cff2f2d244f4e24cbd085c6
#+ method: GET

prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix np: <http://www.nanopub.org/nschema#>
prefix npa: <http://purl.org/nanopub/admin/>
prefix npx: <http://purl.org/nanopub/x/>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>
prefix dct: <http://purl.org/dc/terms/>
prefix fip: <https://w3id.org/fair/fip/terms/>

select distinct ?community ?label ?comment (group_concat(distinct ?domain; separator=" ") as ?domains) where {
  graph npa:graph {
    ?np npa:hasValidSignatureForPublicKey ?pubkey ;
      npx:hasNanopubType fip:FAIR-Implementation-Community ;
      np:hasAssertion ?a .
    ?np dct:created ?date . filter(str(?date) > "2022")
    filter not exists { ?np npx:hasNanopubType npx:ExampleNanopub . }
    filter not exists { ?npx npx:invalidates ?np ; npa:hasValidSignatureForPublicKey ?pubkey . }
  }
  graph ?a {
    ?community a fip:FAIR-Implementation-Community ;
      rdfs:label ?label ;
      rdfs:comment ?comment ;
      fip:has-research-domain ?domain .
    ?community fip:has-research-domain ?__domain_iri .
  }
}
group by ?community ?label ?comment
order by desc(?count)

