#+ summary: Retrieve a mapping of NTA and Rijksmuseum Library URIs to ECARTICO URIs
#+ endpoint: https://sparql.goldenagents.org/sparql
#+ method: GET

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <https://schema.org/>

SELECT ?uri ?ecartico WHERE {
  GRAPH <https://data.goldenagents.org/datasets/u692bc364e9d7fa97b3510c6c0c8f2bb9a0e5123b/ecartico_20211014> {
    ?ecartico a schema:Person ;
            schema:sameAs ?uri .

    FILTER(
      CONTAINS(STR(?uri), "id.rijksmuseum") ||
      CONTAINS(STR(?uri), "/thes/")
    )
  }
}

#+ summary: Get Adverse Outcome Pathways from Adverse Outcome name (literal).
#+ endpoint_in_url: False
#+ tags:
#+   - Adverse Outcome Pathways
#+ defaults:
#+   - AOfilter: 341

prefix aop: <http://identifiers.org/aop/> 
prefix aopo: <http://aopkb.org/aop_ontology#> 
prefix ke: <http://identifiers.org/aop.events/>

SELECT ?KE ?KEname ?AOP ?AOPname WHERE { 
  ?KE a aopo:KeyEvent ; 
  dc:identifier ?AOLookup ; 
  dc:title ?KEname . 
  ?AOP a aopo:AdverseOutcomePathway ; 
  dc:title ?AOPname ; 
  aopo:has_adverse_outcome ?AOLookup.
 FILTER regex (?AOname, ?_AOfilter_en, "i")}

