#+ summary: Natural products structurally similar to chemical classes
#+ description: What are the parent taxa containing the most oleanane triterpenoids (Q108544891) similar to those reported in Quillaja saponaria (Q2382775)?
#+ endpoint: https://query.wikidata.org/bigdata/namespace/wdq/sparql
#+ pagination: 100
#+ method: GET
#+ tags:
#+   - Natural products
#+   - Chemical classes
#+   - Structural similarity

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
#title: What are the parent taxa containing the most oleanane triterpenoids (Q108544891) similar to those reported in Quillaja saponaria (Q2382775)?
PREFIX sachem: <http://bioinfo.uochb.cas.cz/rdf/v1.0/sachem#>
PREFIX idsm: <https://idsm.elixir-czech.cz/sparql/endpoint/>
SELECT DISTINCT ?parent_taxon ?parent_taxon_name (COUNT(DISTINCT ?compound) AS ?count) WHERE {
    SERVICE idsm:wikidata {
        VALUES ?CUTOFF {
            "0.9"^^xsd:double
        }
        SERVICE <https://query.wikidata.org/bigdata/namespace/wdq/sparql> {
            VALUES ?taxon_1 {
                wd:Q2382775
            }
            VALUES ?class {
                wd:Q108544891
            }
            ?structure wdt:P233 ?structure_smiles;
            wdt:P703/(wdt:P171*) ?taxon_1;
            wdt:P279 ?structure_class.
            FILTER(?structure_class = ?class)
        }
        ?compound sachem:similarCompoundSearch [
        sachem:query ?structure_smiles;
        sachem:cutoff ?CUTOFF
        ].
    } hint:Prior hint:runFirst TRUE.
    ?compound wdt:P703/wdt:P171 ?parent_taxon.
    ?parent_taxon wdt:P225 ?parent_taxon_name.
}
GROUP BY ?parent_taxon ?parent_taxon_name
ORDER BY DESC (?count)

#+ summary: "Retrieves all the information about ILIAD Observations"
#+ description: "NOTE: make sure response content type is application/json"
#+ endpoint: "https://www.foodie-cloud.org/sparql?default-graph-uri=http://w3id.org/iliad/dataaset/jf-pilot-sample"
#+ tags:
#+   - json
#+ method: GET
#+ limit: 100
#+ offset: 0
#+ endpoint_in_url: False
#+ transform: {
#+   "description": "?info",
#+   "$anchor": "description",
#+   "@iot.count": "?total",
#+   "@iot.nextLink": "?next_link",
#+   "value": {
#+     "@iot.id": "?id",
#+     "@iot.selfLink": "?id_link",
#+     "phenomenonTime": "?phenomenonTime",
#+     "resultTime": "?resultTime",
#+     "result": {
#+        "densityOfJF": "?densityOfJF",
#+        "quantityOfJF": "?quantityOfJF",
#+        "sampleSizeValue": "?sampleSizeValue",
#+        "speciesScientificName": "?scientificName",
#+        "wormsConcept": "?wormsConcept",
#+        "stingByJF": "?stingByJF",
#+        "beachedJF": "?beachedJF",
#+     },
#+     "Datastream@iot.navigationLink": "?datastream_link",
#+     "FeatureOfInterest@iot.navigationLink": "?feature_link",
#+   }
#+ }

PREFIX iliad-api: <https://w3id.org/iliad/jf/api/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX sosa:  <http://www.w3.org/ns/sosa/>
PREFIX oim-jf:  <http://w3id.org/iliad/oim/jellyfish#> 
PREFIX dwc: <http://rs.tdwg.org/dwc/terms/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX dwc-mbg: <http://mmisw.org/ont/ioos/marine_biogeography/>

SELECT DISTINCT ?info ?id ?id_link ?resultTime ?phenomenonTime ?densityOfJF ?quantityOfJF ?sampleSizeValue ?scientificName ?wormsConcept ?stingByJF ?beachedJF ?datastream_link ?feature_link ?total ?next_link
WHERE {
    ?col a sosa:ObservationCollection ;
      sosa:resultTime ?resultTime ;
			sosa:phenomenonTime ?phenomenonTime ; 
      sosa:hasMember ?s .
    ?s a sosa:Observation ;
			sosa:hasResult ?result .
    OPTIONAL {
      ?result oim-jf:densityOfJF ?densityOfJF ;
        dwc:individualCount ?quantityOfJF ; 
			  dwc:sampleSizeValue ?sampleSizeValue ;
			  dwc:scientificName ?scientificName ;
			  dwc-mbg:aphiaID ?wormsConcept ;
        oim-jf:stingByJF ?stingByJF ;
	      oim-jf:beachedJF ?beachedJF .
    }
		BIND ("OGC SensorThings API - Observations" as ?info)	  
    BIND (REPLACE(STR(?s), "^.*/([^/]*)$", "$1") as ?id)
    BIND (URI(CONCAT('https://w3id.org/iliad/jf/api/v1.0/Observations(', ?id,')')) AS ?id_link)
    BIND (URI(CONCAT('https://w3id.org/iliad/jf/api/v1.0/Observations(', ?id,')/Datastream')) AS ?datastream_link)
    BIND (URI(CONCAT('https://w3id.org/iliad/jf/api/v1.0/Observations(', ?id,')/FeatureOfInterest')) AS ?feature_link)
    {
       SELECT (count(*) as ?total) WHERE { ?x a sosa:Observation }

    }
    BIND (URI(CONCAT('https://w3id.org/iliad/jf/api/v1.0/Observations?$top=',xsd:integer(?_limit),'&$skip=', xsd:integer(COALESCE(?_offset, 0))+xsd:integer(?_limit))) AS ?next_link)
}
ORDER BY ?id

#+ summary: Retrieve PDB IDs
#+ description: Retrieve PDB IDs using the UniProt query serivce. Exploits the sameAs link to UniProt ID and the data mapping in UniProt to PDB ID.
#+ endpoint: https://swel.macs.hw.ac.uk/data/repositories/idpkg
#+ tags:
#+   - UniProt

PREFIX schema: <https://schema.org/>
PREFIX pav: <http://purl.org/pav/>
PREFIX void: <http://rdfs.org/ns/void#>

PREFIX up: <http://purl.uniprot.org/core/>

SELECT DISTINCT ?s ?name ?db
WHERE {
  # Retrieve ID and name from Bioschemas data
    GRAPH ?g {
        ?s a schema:Protein ;
             schema:name ?name ;
             schema:sameAs ?sameAs 
    }
  # Retrieve PDB ID from UniProt
  SERVICE <https://sparql.uniprot.org/sparql> {
	?sameAs a up:Protein ;
    	rdfs:seeAlso ?db .
  	?db up:database <http://purl.uniprot.org/database/PDB>
	}
}

#+ summary: Natural products structurally similar to labels
#+ description: How many compounds are structurally similar to compounds labeled as antibiotics? Results are grouped by the parent taxon of the organism they were found in.
#+ endpoint: https://query.wikidata.org/bigdata/namespace/wdq/sparql
#+ pagination: 100
#+ method: GET
#+ tags:
#+   - Natural products
#+   - Structural similarity

PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
#title: How many compounds are structurally similar to compounds labeled as antibiotics? Results are grouped by the parent taxon of the organism they were found in.
PREFIX sachem: <http://bioinfo.uochb.cas.cz/rdf/v1.0/sachem#>
# prefixes needed for structural similarity search
PREFIX idsm: <https://idsm.elixir-czech.cz/sparql/endpoint/>
SELECT ?parent_taxon ?parent_taxon_name (COUNT(DISTINCT ?compound) AS ?count) WHERE {
    SERVICE idsm:wikidata {
        VALUES ?CUTOFF {
            "0.9"^^xsd:double
        }
        SERVICE <https://query.wikidata.org/bigdata/namespace/wdq/sparql> {
            VALUES ?MESH {
                "D000900"
            }
            ?antibiotic ((wdt:P279*)/wdt:P2868/wdt:P486) ?MESH;
            wdt:P233 ?smiles.
        }
        ?compound sachem:similarCompoundSearch[
        sachem:query ?smiles;
        sachem:cutoff ?CUTOFF
        ].
    } hint:Prior hint:runFirst TRUE.
    ?compound wdt:P703/wdt:P171 ?parent_taxon.
    ?parent_taxon wdt:P225 ?parent_taxon_name.
}
GROUP BY ?parent_taxon ?parent_taxon_name
ORDER BY DESC (?count)

