#+ endpoint: https://graphdb.dumontierlab.com/repositories/shapes-registry
#+ endpoint_in_url: False
#+ summary:  Search for a shapes in shapes files
#+ tags:
#+   - Search
#+ method: GET
#+ pagination: 100
#+ defaults:
#+   - shapelabel: pathway

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dc: <http://purl.org/dc/elements/1.1/>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX schema: <https://schema.org/>
PREFIX sh: <http://www.w3.org/ns/shacl#>
PREFIX shex: <http://www.w3.org/ns/shex#>
PREFIX void: <http://rdfs.org/ns/void#>
SELECT DISTINCT * WHERE { 
    ?shapeFileUri a schema:SoftwareSourceCode ;
        a ?shape_type ;
        rdfs:label ?label ;
        schema:codeRepository ?repository ;
        dcterms:hasPart ?shapes .
    FILTER(?shape_type != schema:SoftwareSourceCode)
    OPTIONAL { ?repository rdfs:comment ?repo_description }
    OPTIONAL { ?shapeFileUri schema:query ?query }
    OPTIONAL { ?shapeFileUri void:sparqlEndpoint ?sparqlEndpoint }
    OPTIONAL { ?shapeFileUri rdfs:comment ?shape_file_description }
    FILTER regex(?shapes, ?_shapelabel,  "i")
}

#+ summary: Get all FIPs for a given community
#+ endpoint: https://query.np.trustyuri.net/repo/type/6a09747868afc83837e38d1bac79362fbcc3e2032cff2f2d244f4e24cbd085c6
#+ method: GET

prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix np: <http://www.nanopub.org/nschema#>
prefix npa: <http://purl.org/nanopub/admin/>
prefix npx: <http://purl.org/nanopub/x/>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>
prefix dct: <http://purl.org/dc/terms/>
prefix fip: <https://w3id.org/fair/fip/terms/>
prefix search: <http://www.openrdf.org/contrib/lucenesail#>

select distinct ?fipnp ?fip ?fiplabel ?community ?communitylabel (group_concat(distinct ?domain; separator=" ") as ?domains) where {
  graph npa:graph {
    ?np npa:hasValidSignatureForPublicKey ?pubkey ;
      dct:created ?date ;
      npx:hasNanopubType fip:FAIR-Implementation-Community ;
      np:hasAssertion ?a .
    ?np npx:introduces|npx:describes ?community .
    ?np dct:created ?date . filter(str(?date) > "2022")
    filter not exists { ?np npx:hasNanopubType npx:ExampleNanopub . }
    filter not exists { ?npx npx:invalidates ?np ; npa:hasValidSignatureForPublicKey ?pubkey . }
  }
  graph ?a {
    ?community a fip:FAIR-Implementation-Community ;
      rdfs:label ?communitylabel ;
      fip:has-research-domain ?domain .
    ?community fip:has-research-domain ?domainx .
  }
  graph <http://purl.org/np/RArRAOwj4QOppEPCR8WVvOBmrX7oRKOrPi-asX-7AY66I#assertion> {
    ?domainx rdfs:subClassOf* ?_domain_iri .
  }
  service <https://query.np.trustyuri.net/repo/type/92efd7a0ea4be4e01ec0817ccec87f975203b30addcc3166a204498ffed73b66> {  # (https://w3id.org/fair/fip/terms/FAIR-Implementation-Profile)
    select ?fipnp ?fip ?fiplabel ?community {
      graph npa:graph {
        ?fipnp np:hasAssertion ?fa .
        optional { ?fipnp rdfs:label ?fiplabel . }
        ?fipnp npx:introduces|npx:describes ?fip .
        ?fipnp npa:hasValidSignatureForPublicKey ?fpubkey .
        ?fipnp npx:hasNanopubType fip:FAIR-Implementation-Profile .
        filter not exists { ?np npx:hasNanopubType npx:ExampleNanopub . }
        filter not exists { ?fipnpx npx:invalidates ?fipnp ; npa:hasValidSignatureForPublicKey ?fpubkey . }
      }
      graph ?fa {
        ?fip fip:declared-by ?community .
      }
    }
  }
}
group by ?fipnp ?fip ?fiplabel ?community ?communitylabel

#+ summary: Query in the Golden Agents ontology to list all works and their authors, publishers and involved persons (including their role) in the Golden Agents Occasional Poetry dataset (Gelegenheidsgedichten).
#+ endpoint: https://sparql.goldenagents.org/
#+ method: GET
#+ tags:
#+  - ggd
#+  - gelegenheidsgedichten
#+  - stcn
#+  - nta

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX ga: <https://data.goldenagents.org/ontology/>

SELECT * WHERE {

  ?book a ga:WritingArtifact ;
        ga:hasTitle ?title ;
        ga:writtenBy ?author ;
        ga:publishedBy|ga:printedBy ?printerOrPublisher ;
        ga:hasContent/ga:isAbout ?event .

  ?author a ga:Writer ;
          ga:hasName ?authorName ;
          ga:hasGender ?authorGender .

  ?publisher a ga:PrinterOrPublisher ;
             ga:hasName ?publisherName .

  ?event a ga:Event ;
         ga:hasXSDDate ?eventDate ;
         rdf:type ?eventType ;
         ga:participationOf ?person .

  ?role a ga:Role ;
        ga:carriedAs ?roleType ;
        ga:carriedBy ?person ;
        ga:carriedIn ?event .

  ?roleType a ga:RoleType ;
            rdfs:label ?roleTypeName .

  ?person a ga:Person ;
          ga:hasName ?personName ;
          ga:gender ?personGender .

}

