#+ summary: Scholarly articles from Wolfender's lab
#+ description: Scholarly articles from Wolfender's lab
#+ endpoint: https://query.wikidata.org/bigdata/namespace/wdq/sparql
#+ pagination: 100
#+ method: GET
#+ tags:
#+   - Scholarly articles

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX pq: <http://www.wikidata.org/prop/qualifier/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX bd: <http://www.bigdata.com/rdf#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
#title: Scholarly articles from Wolfender's lab
SELECT DISTINCT (MIN(?dates) AS ?date) ?title ?journal ?doi ?work (GROUP_CONCAT(DISTINCT ?authorLabel; SEPARATOR = ", ") AS ?authors) WHERE {
    SELECT DISTINCT ?authorLabel ?order ?dates ?title ?journal ?doi ?work WHERE {
        SERVICE <https://query-scholarly.wikidata.org/sparql> {
            {
                SELECT DISTINCT ?work ?author_statement ?dates ?doi ?journal ?title WHERE {
                    {
                        SELECT DISTINCT ?work ?datetimes WHERE {
                            ?work wdt:P50 wd:Q56084663;                         # Jean-Luc Wolfender
                            wdt:P577 ?datetimes.
                            FILTER((YEAR(?datetimes)) >= ((YEAR(NOW())) - 20 )) # last 20 years
                        }
                    }
                    hint:Prior hint:runFirst TRUE.
                    ?work wdt:P1433 ?journal_;
                    wdt:P356 ?doi;
                    p:P50 ?author_statement.
                    BIND(xsd:date(?datetimes) AS ?dates)
                    SERVICE wikibase:label {
                        bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,en".
                        ?journal_ rdfs:label ?journal.
                        ?work rdfs:label ?title.
                    }
                }
            }
            hint:Prior hint:runFirst TRUE.
            ?author_statement ps:P50 ?author;
            pq:P1545 ?order_.
            BIND(xsd:integer(?order_) AS ?order)
            SERVICE wikibase:label {
                bd:serviceParam wikibase:language "[AUTO_LANGUAGE],mul,en".
                ?author rdfs:label ?authorLabel.
            }
        }
    }
    ORDER BY (?order)
}
GROUP BY ?title ?journal ?doi ?work
ORDER BY DESC (?date)

#+ summary: Which taxa have children (or themselves) with known chemicals, genes, and proteins?
#+ description: Which taxa have children (or themselves) with known chemicals, genes, and proteins?
#+ endpoint: https://query.wikidata.org/bigdata/namespace/wdq/sparql
#+ pagination: 100
#+ method: GET
#+ tags:
#+   - Omics

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX hint: <http://www.bigdata.com/queryHints#>
#title: Which taxa have children (or themselves) with known chemicals, genes, and proteins? (search)
SELECT ?taxon ?child (COUNT(DISTINCT ?g) AS ?genome) (COUNT(DISTINCT ?m) AS ?metabolome) (COUNT(DISTINCT ?p) AS ?proteome) WHERE {
    {
        SELECT ?taxon ?child ?thing WHERE {
            VALUES ?taxon {
                wd:Q31856
            }
            ?taxon ^(wdt:P171*) ?child.
            hint:Prior hint:rangeSafe TRUE.
            ?child ^wdt:P703 ?thing.
            hint:Prior hint:rangeSafe TRUE.
        }
    }
    {
        SELECT * WHERE {
            VALUES ?chemical {
                wd:Q113145171
                wd:Q59199015
            }
            VALUES ?gene {
                wd:Q7187
            }
            VALUES ?protein {
                wd:Q8054
            }
            {
                ?thing wdt:P31 ?chemical.
                hint:Prior hint:rangeSafe TRUE.
                BIND(?thing AS ?m)
            }
            UNION
            {
                ?thing wdt:P31 ?protein.
                hint:Prior hint:rangeSafe TRUE.
                BIND(?thing AS ?p)
            }
            UNION
            {
                ?thing wdt:P31 ?gene.
                hint:Prior hint:rangeSafe TRUE.
                BIND(?thing AS ?g)
            }
        }
    }
}
GROUP BY ?taxon ?child
HAVING (((?genome > 0 ) || (?metabolome > 0 )) || (?proteome > 0 ))

