#+ summary: Natural products with bioactivity in Actinomycetes
#+ description: Which natural products with known bioactivities were isolated from Actinomycetes (Q62606918), between 2014 and 2019, with related organisms and references?
#+ endpoint: https://query-main.wikidata.org/bigdata/namespace/wdq/sparql
#+ pagination: 100
#+ method: GET
#+ tags:
#+   - Natural products

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX pr: <http://www.wikidata.org/prop/reference/>
PREFIX prov: <http://www.w3.org/ns/prov#>
#title: Which natural products with known bioactivities were isolated from Actinomycetes (Q62606918), between 2014 and 2019, with related organisms and references?
SELECT ?organism ?organism_name ?compound ?compound_smiles ?bioactivity ?isolation_reference ?reference_title WHERE {
    ?organism (wdt:P171*) wd:Q62606918;
    wdt:P225 ?organism_name.
    ?compound wdt:P235 ?compound_id;
    wdt:P233 ?compound_smiles;
    p:P703 ?statement;
    (wdt:P2868/wdt:P486) ?meshId.
    ?mesh wdt:P486 ?meshId;
    rdfs:label ?bioactivity.
    FILTER(LANGMATCHES(LANG(?bioactivity), "EN"))
    ?statement ps:P703 ?organism;
    prov:wasDerivedFrom ?ref.
    ?ref pr:P248 ?isolation_reference.
    SERVICE <https://query-scholarly.wikidata.org/sparql> {
      ?isolation_reference wdt:P1476 ?reference_title;
      wdt:P577 ?reference_date.
    }
    FILTER(((YEAR(?reference_date)) >= 2014 ) && ((YEAR(?reference_date)) <= 2019 ))
}
LIMIT 10000

#+ summary: Get RDF representation of a given FAIR Implementation Profile
#+ method: GET
#+ endpoint: https://query.knowledgepixels.com/repo/full

prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix np: <http://www.nanopub.org/nschema#>
prefix npa: <http://purl.org/nanopub/admin/>
prefix npx: <http://purl.org/nanopub/x/>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>
prefix dct: <http://purl.org/dc/terms/>
prefix fip: <https://w3id.org/fair/fip/terms/>

construct {
  ?subj1 ?pred1 ?obj1 .
  ?subj2 ?pred2 ?obj2 .
  ?subj3 ?pred3 ?obj3 .
  ?fer rdfs:label ?fer_label_x .
} where {
  optional { <x:> <x:> ?_fipnp_iri }
  graph npa:graph {
    ?_fipnp_iri npx:hasNanopubType fip:FAIR-Implementation-Profile ;
      np:hasAssertion ?assertion1 .
  }
  graph ?assertion1 {
    ?fip a fip:FAIR-Implementation-Profile ;
      fip:has-declaration-index ?index_np .
    ?subj1 ?pred1 ?obj1 .
  }
  graph npa:graph {
    ?index_np np:hasAssertion ?assertion2 .
    ?index_np npx:hasNanopubType npx:NanopubIndex .
  }
  graph ?assertion2 {
    ?index_np npx:includesElement ?decl_np .
    ?subj2 ?pred2 ?obj2 .
  }
  graph npa:graph {
    ?decl_np np:hasAssertion ?assertion3 .
    ?decl_np npx:hasNanopubType fip:FIP-Declaration .
  }
  graph ?assertion3 {
    ?subj fip:refers-to-question ?question .
    values ?declares_pred { fip:declares-current-use-of fip:declares-planned-use-of fip:declares-planned-development-of fip:declares-planned-replacement-of }
    ?subj ?declares_pred ?fer .
    ?subj3 ?pred3 ?obj3 .
  }
  optional {
    graph npa:graph {
      ?fer_np npa:hasValidSignatureForPublicKey ?pubkey ;
        np:hasAssertion ?assertion3 .
      filter not exists { ?fer_npx npx:invalidates ?fer_np ; npa:hasValidSignatureForPublicKey ?pubkey . }
    }
    graph ?assertion3 {
      ?fer rdfs:label ?fer_label_x .
    }
  }
}

#+ summary: Among the SIRIUS structural annotations from Tabernaemontana coffeoides (Apocynaceae) seeds extract, which ones are reported in the Tabernaemontana genus?
#+ description: Among the SIRIUS structural annotations from Tabernaemontana coffeoides (Apocynaceae) seeds extract, which ones are reported in the Tabernaemontana genus?
#+ endpoint: https://biosoda.unil.ch/graphdb/repositories/emi-dbgi
#+ tags:
#+	- DBGI

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX prov: <http://www.w3.org/ns/prov#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX emi: <https://purl.org/emi#>
PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX pr: <http://www.wikidata.org/prop/reference/>

SELECT DISTINCT ?ik2d ?genus
WHERE
    {
    ?material sosa:hasSample ?extract ;
        sosa:isSampleOf ?organe .
    ?organe emi:inTaxon ?wd_sp .
    ?wd_sp rdfs:label "tabernaemontana coffeoides" .
    ?extract sosa:isFeatureOfInterestOf ?lcms .
    ?lcms sosa:hasResult ?feature_list .
    ?feature_list emi:hasLCMSFeature ?feature .
    ?feature emi:hasAnnotation ?sirius_annotation .
    ?sirius_annotation a emi:StructuralAnnotation ;
        prov:wasGeneratedBy ?activity ;
        emi:hasChemicalStructure ?ik2d .
    ?activity prov:wasAssociatedWith <https://bio.informatik.uni-jena.de/software/sirius> .
    ?ik2d emi:hasSMILES ?smiles ;
        emi:isInChIKey2DOf ?ik .
    ?ik emi:isInChIKeyOf ?wd_id .
	{
        SELECT DISTINCT ?wd_id ?genus WHERE {
            ?material sosa:hasSample ?extract ;
                sosa:isSampleOf ?organe .
            ?organe emi:inTaxon ?wd_sp .
            ?wd_sp rdfs:label "tabernaemontana coffeoides" .
            OPTIONAL {
                SERVICE <https://query.wikidata.org/sparql> {
                    ?wd_sp wdt:P225 ?species_name .
                    ?genus wdt:P31 wd:Q16521 ;
                        wdt:P105 wd:Q34740 ;
                        ^wdt:P171* ?wd_sp .
                    ?childtaxa wdt:P171* ?genus .
                    ?wd_id wdt:P703 ?childtaxa
                }
            }
        }
    }
}

