select ?gemeente (min(?begin) as ?begin) ?eind ?usurper ?amsterdamCode ?amco{
  ?gemeente a gg:Municipality.
  optional { ?gemeente gg:endDate ?eind. 
  			 ?gemeente gg:absorbedBy ?usurper }
  {
    ?gemeente gg:startDate ?begin.
  } union {
    filter not exists { ?gemeente gg:startDate ?begin. }
    ?gemeente geo:hasGeometry/gg:year ?geoJaar.
    bind(xsd:date(?geoJaar) as ?begin)
  }
  OPTIONAL {
    ?amsterdamCode rdf:type gg:AmsterdamCode .
    ?amsterdamCode gg:identifies ?gemeente .
    bind(substr(str(?amsterdamCode), 41) as ?amco) }

}
order by ?gemeente

#+ summary: A query for co-authorships between affiliates of HiTS
#+ endpoint: https://query.wikidata.org/sparql
#+ tags:
#+   - bibliometrics
#defaultView:Graph

SELECT
  ?author1 ?author1Label ?image1 ?rgb
  ?author2 ?author2Label ?image2 
WITH {
  SELECT
    ?author1 (SAMPLE(?image1_) AS ?image1)
    ?author2 (SAMPLE(?image2_) AS ?image2)
    (SAMPLE(?rgb_) AS ?rgb)
  WHERE {
    wd:Q107392274 ^wdt:P361* / ^( wdt:P108 | wdt:P1416 | wdt:P463 ) ?author1 , ?author2 . 
    ?work wdt:P50 ?author1 , ?author2 .

    # Only display co-authorship for certain types of documents
    # Journal and conference articles, books, not (yet?) software
    VALUES ?publication_type { wd:Q13442814 wd:Q571 wd:Q26973022 wd:Q17928402 wd:Q947859 wd:Q54670950 }
    FILTER EXISTS { ?work wdt:P31 ?publication_type . }

    # No self-links.
    FILTER (?author1 != ?author2)

    # Images
    OPTIONAL { ?author1 wdt:P18 ?image1_ }
    OPTIONAL { ?author2 wdt:P18 ?image2_ }

    # Coloring of the nodes
    BIND("FFFFFF" AS ?rgb_)
  }
  GROUP BY ?author1 ?author2
} AS %result
WHERE {
  INCLUDE %result
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,da,de,es,fr,jp,sv,ru,zh".
  }
}

#+ summary: Get Stressor Chemicals described to initiate AOPs that lead to selected Adverse Outcome (ID).
#+ endpoint_in_url: False
#+ tags:
#+   - Chemicals
#+ defaults:
#+   - aofilter: 344

prefix dc:  <http://purl.org/dc/elements/1.1/> 
prefix aop: <http://identifiers.org/aop/> 
prefix aopo: <http://aopkb.org/aop_ontology#> 
prefix ke: <http://identifiers.org/aop.events/>
PREFIX nci: <http://ncicb.nci.nih.gov/xml/owl/EVS/Thesaurus.owl#>

SELECT ?AO ?AOname ?StressorName ?ChemicalName WHERE { 
  ?AO a aopo:KeyEvent ; 
  dc:identifier ?AOLookup ; 
  dc:title ?AOname . 
  ?AOP a aopo:AdverseOutcomePathway ; 
  aopo:has_adverse_outcome ?AOLookup ;
  nci:C54571 ?Stressor .
  ?Stressor dc:title ?StressorName.
  OPTIONAL {?Stressor aopo:has_chemical_entity ?Chemical. ?Chemical dc:title ?ChemicalName.}
  BIND(IRI(CONCAT("http://identifiers.org/aop.events/",?_aofilter_integer)) AS ?AOf )
  FILTER (?AO = ?AOf)}
  ORDER BY DESC (?AO)

